package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="servicios", uniqueConstraints=@UniqueConstraint(columnNames={"empresa_id","codigo"}))
public class Servicio { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; private String codigo; private String nombre; private String descripcion; private BigDecimal precio=BigDecimal.ZERO; private Boolean activo=true; private String tipo="CONSULTA"; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="especialidad_id") private Especialidad especialidad; @Column(name="duracion_minutos") private Integer duracionMinutos; @Column(name="disponible_citas") private Boolean disponibleCitas=true; private Boolean facturable=true; @Column(name="tasa_impuesto") private BigDecimal tasaImpuesto=BigDecimal.ZERO;
 public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public String getCodigo(){return codigo;} public void setCodigo(String v){codigo=v;} public String getNombre(){return nombre;} public void setNombre(String v){nombre=v;} public String getDescripcion(){return descripcion;} public void setDescripcion(String v){descripcion=v;} public BigDecimal getPrecio(){return precio;} public void setPrecio(BigDecimal v){precio=v;} public Boolean getActivo(){return activo;} public void setActivo(Boolean v){activo=v;} public String getTipo(){return tipo;} public void setTipo(String v){tipo=v;} public Especialidad getEspecialidad(){return especialidad;} public void setEspecialidad(Especialidad v){especialidad=v;} public Integer getDuracionMinutos(){return duracionMinutos;} public void setDuracionMinutos(Integer v){duracionMinutos=v;} public Boolean getDisponibleCitas(){return disponibleCitas;} public void setDisponibleCitas(Boolean v){disponibleCitas=v;} public Boolean getFacturable(){return facturable;} public void setFacturable(Boolean v){facturable=v;} public BigDecimal getTasaImpuesto(){return tasaImpuesto;} public void setTasaImpuesto(BigDecimal v){tasaImpuesto=v;} }
